<script setup>const f=reactive({name:'',nik:'',email:'',company:'',phone:'',instagram:'',password:''});const msg=ref('');async function submit(){try{await $fetch('/api/auth/signup',{method:'POST',body:f});msg.value='Pendaftaran dikirim. Tunggu persetujuan admin.'}catch(e){msg.value=e.data?.statusMessage||'Gagal mendaftar'}}</script><template><main class="max-w-xl mx-auto p-8"><form class="panel space-y-3" @submit.prevent="submit"><h1 class="text-2xl font-black">Daftar PCI</h1><input v-model="f.name" class="input" placeholder="Nama" required><input v-model="f.nik" class="input" placeholder="NIK" required><input v-model="f.email" type="email" class="input" placeholder="Email" required><input v-model="f.company" class="input" placeholder="Nama perusahaan" required><input v-model="f.phone" class="input" placeholder="Nomor WhatsApp"><input v-model="f.instagram" class="input" placeholder="Instagram"><input v-model="f.password" type="password" minlength="10" class="input" placeholder="Password min. 10 karakter" required><button class="btn-primary w-full">Kirim pendaftaran</button><p>{{msg}}</p><NuxtLink to="/login" class="text-blue-700">Kembali</NuxtLink></form></main></template>